class Solution {
public:
    int countDistinct(string s) {
        unordered_set<string> seen;
        int n = s.size();
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j <= n; j++)
                seen.insert(s.substr(i, j - i));
        return (int)seen.size();
    }
};

