class Solution:
    def countDistinct(self, s: str) -> int:
        root = {}
        count = 0
        n = len(s)
        for i in range(n):
            node = root
            for j in range(i, n):
                ch = s[j]
                if ch not in node:
                    node[ch] = {}
                    count += 1
                node = node[ch]
        return count

