class Solution {
public:
    int countDistinct(string s) {
        vector<array<int, 26>> trie(1);
        int count = 0, n = s.size();
        for (int i = 0; i < n; i++) {
            int node = 0;
            for (int j = i; j < n; j++) {
                int c = s[j] - 'a';
                if (trie[node][c] == 0) {
                    trie[node][c] = trie.size();
                    trie.push_back({});
                    count++;
                }
                node = trie[node][c];
            }
        }
        return count;
    }
};

