class Solution {
    public int countDistinct(String s) {
        int n = s.length();
        int[][] trie = new int[n * (n + 1) / 2 + 1][26];
        int nodes = 1, count = 0;
        for (int i = 0; i < n; i++) {
            int node = 0;
            for (int j = i; j < n; j++) {
                int c = s.charAt(j) - 'a';
                if (trie[node][c] == 0) {
                    trie[node][c] = nodes++;
                    count++;
                }
                node = trie[node][c];
            }
        }
        return count;
    }
};

