class Solution {
public:
    int countDistinct(string s) {
        int n = s.size();
        const long long M1 = 1000000007LL, M2 = 998244353LL, B = 131;
        vector<long long> h1(n + 1, 0), h2(n + 1, 0), p1(n + 1, 1), p2(n + 1, 1);
        for (int i = 0; i < n; i++) {
            long long o = s[i];
            h1[i + 1] = (h1[i] * B + o) % M1;
            h2[i + 1] = (h2[i] * B + o) % M2;
            p1[i + 1] = p1[i] * B % M1;
            p2[i + 1] = p2[i] * B % M2;
        }
        long long total = 0;
        unordered_set<long long> seen;
        for (int len = 1; len <= n; len++) {
            seen.clear();
            for (int i = 0; i + len <= n; i++) {
                long long k1 = ((h1[i + len] - h1[i] * p1[len]) % M1 + M1) % M1;
                long long k2 = ((h2[i + len] - h2[i] * p2[len]) % M2 + M2) % M2;
                seen.insert(k1 << 32 | k2);
            }
            total += (long long)seen.size();
        }
        return (int)total;
    }
};

