var countDistinct = function(s) {
    const n = s.length;
    const M1 = 1000000007n, M2 = 998244353n, B = 131n;
    const h1 = [0n], h2 = [0n], p1 = [1n], p2 = [1n];
    for (let i = 0; i < n; i++) {
        const o = BigInt(s.charCodeAt(i));
        h1.push((h1[i] * B + o) % M1);
        h2.push((h2[i] * B + o) % M2);
        p1.push(p1[i] * B % M1);
        p2.push(p2[i] * B % M2);
    }
    let total = 0;
    for (let len = 1; len <= n; len++) {
        const seen = new Set();
        for (let i = 0; i + len <= n; i++) {
            const k1 = ((h1[i + len] - h1[i] * p1[len]) % M1 + M1) % M1;
            const k2 = ((h2[i + len] - h2[i] * p2[len]) % M2 + M2) % M2;
            seen.add(k1 + ',' + k2);
        }
        total += seen.size;
    }
    return total;
};
